SELECT MAX(c.Score) AS MaxScore, COUNT(*) AS CntAtMax, COUNT(*) OVER () AS TotalQualifyingComments
FROM comments c JOIN posts p ON c.PostId = p.Id
WHERE p.ViewCount BETWEEN 100 AND 150 AND c.Score = (SELECT MAX(c2.Score) FROM comments c2 JOIN posts p2 ON c2.PostId = p2.Id WHERE p2.ViewCount BETWEEN 100 AND 150);
